157: function extractAltitudeInput(sig: SignificatorSnapshot): AltitudeInput {
158:   const ordinals = ALL_LINES.map(l => stageOrdinal(sig.altitudes[l]));
159:   const mean = ordinals.reduce((a, b) => a + b, 0) / ordinals.length;
160:   const variance = ordinals.reduce((sum, o) => sum + (o - mean) ** 2, 0) / ordinals.length;
161:   // Normalise spread to 0-1 range (max possible stddev is ~3.5 for 8 stages)
162:   const spread = Math.sqrt(variance) / 3.5;
163: 
164:   const lowestOrdinal = Math.min(...ordinals);
165:   const highestOrdinal = Math.max(...ordinals);
166: 
167:   const ALL_STAGES: readonly Stage[] = [
168:     'Infrared', 'Magenta', 'Red', 'Amber', 'Orange', 'Green', 'Turquoise', 'White',
169:   ];
170:   const lowestAltitude = ALL_STAGES[lowestOrdinal] as Stage;
171:   const highestAltitude = ALL_STAGES[highestOrdinal] as Stage;
172: 
