1: /**
2:  * PriorityComputation — weighted priority formula for encounter ranking.
3:  * Spec: foundations/24 §3.2
4:  *
5:  * priority = 0.25 * theta_urgency
6:  *          + 0.20 * shadow_activation
7:  *          + 0.15 * polarity_alignment
8:  *          + 0.15 * transformation_readiness
9:  *          + 0.10 * drive_correction
10:  *          + 0.10 * narrative_coherence
11:  *          + 0.05 * session_fit
12:  */
13: import type { Drive } from '../domain/Drive.js';
14: import type { Significator } from '../domain/Significator.js';
15: import { stageOrdinal } from '../domain/Stage.js';
16: import type { EncounterCandidate, WorldState } from './CandidateGeneration.js';
17: import { computeCellStaleness, DEFAULT_THETA_PARAMS } from './ThetaDecay.js';
18: 
19: export interface SessionContext {
20:   readonly encountersSoFar: number;
21:   readonly sessionDurationMs: number;
22:   readonly targetSessionLength: number; // encounters
23:   readonly recentLines: readonly string[];
24:   readonly estimatedTimeAvailable?: number; // ms
25:   readonly inferredEnergy?: 'high' | 'moderate' | 'low';
26:   readonly patienceSignals?: {
27:     readonly avoidanceRate: number;
28:     readonly responseLatencyTrend: 'decreasing' | 'stable' | 'increasing';
29:     readonly earlyExits: number;
30:   };
31:   readonly forceLine?: string;
32:   readonly forceStage?: string;
33:   readonly forceModality?: string;
34: }
35: 
36: export interface PriorityWeights {
37:   readonly thetaUrgency: number;
38:   readonly shadowActivation: number;
39:   readonly polarityAlignment: number;
40:   readonly transformationReadiness: number;
41:   readonly driveCorrection: number;
42:   readonly narrativeCoherence: number;
43:   readonly sessionFit: number;
44: }
45: 
46: export const DEFAULT_WEIGHTS: PriorityWeights = {
47:   thetaUrgency: 0.25,
48:   shadowActivation: 0.20,
49:   polarityAlignment: 0.15,
50:   transformationReadiness: 0.15,
51:   driveCorrection: 0.10,
52:   narrativeCoherence: 0.10,
53:   sessionFit: 0.05,
54: };
55: 
56: export function computePriority(
57:   candidate: EncounterCandidate,
58:   sig: Significator,
59:   world: WorldState,
60:   session: SessionContext,
61:   now: number,
62:   weights: PriorityWeights = DEFAULT_WEIGHTS,
63: ): number {
64:   const t = computeThetaUrgency(candidate, sig, now);
65:   const s = computeShadowActivation(candidate, sig);
66:   const p = computePolarityAlignment(candidate, sig);
67:   const tr = computeTransformationReadiness(candidate, sig);
68:   const d = computeDriveCorrection(candidate, sig, world);
69:   const n = computeNarrativeCoherence(candidate, world);
70:   const sf = computeSessionFit(candidate, session);
71: 
72:   const baseScore = weights.thetaUrgency * t
73:     + weights.shadowActivation * s
74:     + weights.polarityAlignment * p
75:     + weights.transformationReadiness * tr
76:     + weights.driveCorrection * d
77:     + weights.narrativeCoherence * n
78:     + weights.sessionFit * sf;
79: 
80:   // Novelty bonus: candidates with fewer traces get a meaningful boost
81:   // Unvisited cells (0 traces) get +0.25, visited cells get diminishing returns
82:   const cellKey = `${candidate.line}:${candidate.stage}`;
83:   const cell = sig.polarity.cells[cellKey];
84:   const traceCount = cell?.traceCount ?? 0;
85:   const noveltyBonus = traceCount === 0 ? 0.25 : Math.max(0, 0.25 - traceCount * 0.03);
86: 
87:   // Developmental need: prioritize lines where the player is weakest
